class Solution:
    def generateSentences(self, synonyms: List[List[str]], text: str) -> List[str]:
        groups = {}
        for a, b in synonyms:
            sa = groups.setdefault(a, {a})
            sb = groups.setdefault(b, {b})
            merged = sa | sb
            for w in merged:
                groups[w] = merged
        words = text.split()
        res = []

        def dfs(i, cur):
            if i == len(words):
                res.append(" ".join(cur))
                return
            for w in groups.get(words[i], {words[i]}):
                cur.append(w)
                dfs(i + 1, cur)
                cur.pop()

        dfs(0, [])
        return sorted(res)

