class Solution {
public:
    vector<string> generateSentences(vector<vector<string>>& synonyms, string text) {
        unordered_map<string, set<string>> groups;
        for (auto& p : synonyms) {
            auto& sa = groups[p[0]]; sa.insert(p[0]);
            auto& sb = groups[p[1]]; sb.insert(p[1]);
            set<string> merged = sa;
            merged.insert(sb.begin(), sb.end());
            for (auto& w : merged) groups[w] = merged;
        }
        vector<string> words;
        stringstream ss(text);
        string w;
        while (ss >> w) words.push_back(w);
        vector<string> res, cur;
        function<void(int)> dfs = [&](int i) {
            if (i == (int)words.size()) {
                string s;
                for (int j = 0; j < (int)cur.size(); ++j) {
                    if (j) s += ' ';
                    s += cur[j];
                }
                res.push_back(s);
                return;
            }
            auto it = groups.find(words[i]);
            if (it == groups.end()) {
                cur.push_back(words[i]); dfs(i + 1); cur.pop_back();
            } else {
                for (auto& c : it->second) { cur.push_back(c); dfs(i + 1); cur.pop_back(); }
            }
        };
        dfs(0);
        sort(res.begin(), res.end());
        return res;
    }
};

