class Solution {
    public List<String> generateSentences(List<List<String>> synonyms, String text) {
        Map<String, Set<String>> groups = new HashMap<>();
        for (List<String> p : synonyms) {
            Set<String> sa = groups.computeIfAbsent(p.get(0), k -> new HashSet<>());
            sa.add(p.get(0));
            Set<String> sb = groups.computeIfAbsent(p.get(1), k -> new HashSet<>());
            sb.add(p.get(1));
            Set<String> merged = new HashSet<>(sa);
            merged.addAll(sb);
            for (String w : merged) groups.put(w, merged);
        }
        String[] words = text.split(" ");
        List<String> res = new ArrayList<>();
        dfs(words, 0, new ArrayList<>(), groups, res);
        Collections.sort(res);
        return res;
    }

    private void dfs(String[] words, int i, List<String> cur,
                     Map<String, Set<String>> groups, List<String> res) {
        if (i == words.length) {
            res.add(String.join(" ", cur));
            return;
        }
        Set<String> cand = groups.getOrDefault(words[i], Collections.singleton(words[i]));
        for (String w : cand) {
            cur.add(w);
            dfs(words, i + 1, cur, groups, res);
            cur.remove(cur.size() - 1);
        }
    }
}

