                if (!idx.count(w)) { idx[w] = parent.size(); parent.push_back(parent.size()); }
        for (auto& p : synonyms) {
            int ra = find(idx[p[0]]), rb = find(idx[p[1]]);
            if (ra != rb) parent[ra] = rb;
        }
        unordered_map<int, vector<string>> comp;
        for (auto& [w, i] : idx) comp[find(i)].push_back(w);
        for (auto& [r, v] : comp) sort(v.begin(), v.end());

        vector<string> words; stringstream ss(text); string t;
