class Solution {
    private int[] parent;
    private int find(int x) { while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }

    public List<String> generateSentences(List<List<String>> synonyms, String text) {
        Map<String, Integer> idx = new HashMap<>();
        for (List<String> p : synonyms)
            for (String w : p)
                idx.putIfAbsent(w, idx.size());
        parent = new int[idx.size()];
        for (int i = 0; i < parent.length; i++) parent[i] = i;
        for (List<String> p : synonyms) {
            int ra = find(idx.get(p.get(0))), rb = find(idx.get(p.get(1)));
            if (ra != rb) parent[ra] = rb;
        }
        Map<Integer, List<String>> comp = new HashMap<>();
        for (Map.Entry<String, Integer> e : idx.entrySet())
            comp.computeIfAbsent(find(e.getValue()), k -> new ArrayList<>()).add(e.getKey());
        for (List<String> v : comp.values()) Collections.sort(v);

        String[] words = text.split(" ");
        List<String> res = new ArrayList<>();
        dfs(words, 0, new ArrayList<>(), idx, comp, res);
        Collections.sort(res);
        return res;
    }

    private void dfs(String[] words, int i, List<String> cur, Map<String, Integer> idx,
                     Map<Integer, List<String>> comp, List<String> res) {
        if (i == words.length) { res.add(String.join(" ", cur)); return; }
        List<String> cand = idx.containsKey(words[i])
                ? comp.get(find(idx.get(words[i]))) : Collections.singletonList(words[i]);
        for (String w : cand) { cur.add(w); dfs(words, i + 1, cur, idx, comp, res); cur.remove(cur.size() - 1); }
    }
}

