var generateSentences = function(synonyms, text) {
    const idx = new Map();
    let n = 0;
    for (const [a, b] of synonyms) for (const w of [a, b]) if (!idx.has(w)) idx.set(w, n++);
    const parent = Array.from({length: n}, (_, i) => i);
    const find = x => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
    for (const [a, b] of synonyms) {
        const ra = find(idx.get(a)), rb = find(idx.get(b));
        if (ra !== rb) parent[ra] = rb;
    }
    const comp = new Map();
    for (const [w, i] of idx) {
        const r = find(i);
        if (!comp.has(r)) comp.set(r, []);
        comp.get(r).push(w);
    }
    for (const v of comp.values()) v.sort();
    const words = text.split(' '), res = [];
    const dfs = (i, cur) => {
        if (i === words.length) { res.push(cur.join(' ')); return; }
        const cand = idx.has(words[i]) ? comp.get(find(idx.get(words[i]))) : [words[i]];
        for (const w of cand) { cur.push(w); dfs(i + 1, cur); cur.pop(); }
    };
    dfs(0, []);
    return res.sort();
};
